-- rds-activation/v1 fragment 30: create the complete HoopDb role set as the executor,
-- every role NOLOGIN first, each with its exact role settings.
--
-- hoopdb_activation.role_spec is generated by the driver from the repository's role
-- SQL (rds_migration_roles.sql inventory, session_consumer_roles.sql, every operator
-- *_role.sql and session_directory_search_worker.sql). It holds hoop,
-- sessions_pipeline_runtime and every fixed service role, with LOGIN and the settings
-- those files would apply (for example statement_timeout=5s, lock_timeout=2s,
-- idle_in_transaction_session_timeout=10s). After activation, hoop holds no ADMIN
-- and no CREATEROLE, so none of those files may still need to create or alter a
-- role. A unit test fails when a file creates or alters a role that is missing here.
--
-- On PostgreSQL 16+ the executor, as a non-superuser CREATEROLE creator, gets one
-- automatic edge per created role: role <- executor, ADMIN true, INHERIT false,
-- SET false, grantor = the bootstrap superuser (rdsadmin). That is the only edge
-- allowed here. LOGIN is armed later, in 40, only after this graph is proven.
DO $rds_activation_30$
DECLARE
  v_spec jsonb := current_setting('hoopdb_activation.role_spec')::jsonb;
  v_role jsonb;
  v_setting text;
  v_bad text[] := '{}';
  v_row record;
BEGIN
  IF current_user::text <> 'hoopdb_activation_executor'
     OR session_user::text <> current_setting('hoopdb_activation.provisioner') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'rds-activation fragment 30 must run as hoopdb_activation_executor';
  END IF;
  FOR v_role IN SELECT e FROM jsonb_array_elements(v_spec) e ORDER BY e->>'name' LOOP
    EXECUTE format('CREATE ROLE %I NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS',
                   v_role->>'name');
    FOR v_setting IN SELECT jsonb_array_elements_text(v_role->'settings') LOOP
      IF v_setting !~ '^[a-z_]+=[A-Za-z0-9]+$' THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = format('rds-activation: malformed setting %L', v_setting);
      END IF;
      EXECUTE format('ALTER ROLE %I SET %I = %L', v_role->>'name', split_part(v_setting, '=', 1), split_part(v_setting, '=', 2));
    END LOOP;
  END LOOP;

  -- The exact grantor graph at this point: each HoopDb role has exactly its one
  -- automatic creator edge, and no HoopDb role is a member or a grantor of anything.
  FOR v_row IN
    SELECT r.rolname AS role, pg_get_userbyid(m.member) AS member, pg_get_userbyid(m.grantor) AS grantor,
           g.rolsuper AS grantor_super, m.admin_option, m.inherit_option, m.set_option,
           m.roleid = r.oid AS as_role
      FROM pg_roles r
      JOIN pg_auth_members m ON r.oid IN (m.roleid, m.member, m.grantor)
      JOIN pg_roles g ON g.oid = m.grantor
     WHERE r.rolname IN (SELECT e->>'name' FROM jsonb_array_elements(v_spec) e)
  LOOP
    IF NOT (v_row.as_role AND v_row.member = 'hoopdb_activation_executor'
            AND v_row.grantor = 'rdsadmin' AND v_row.grantor_super
            AND v_row.admin_option AND NOT v_row.inherit_option AND NOT v_row.set_option) THEN
      v_bad := v_bad || format('%I: member %I grantor %I ADMIN=%s INHERIT=%s SET=%s', v_row.role, v_row.member,
                               v_row.grantor, v_row.admin_option, v_row.inherit_option, v_row.set_option)::text;
    END IF;
  END LOOP;
  IF (SELECT count(*) FROM pg_auth_members WHERE member = 'hoopdb_activation_executor'::regrole
        AND roleid IN (SELECT oid FROM pg_roles WHERE rolname IN (SELECT e->>'name' FROM jsonb_array_elements(v_spec) e)))
     <> jsonb_array_length(v_spec) THEN
    v_bad := v_bad || 'a created role lacks its creator edge'::text;
  END IF;
  IF cardinality(v_bad) > 0 THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'rds-activation: unexpected grantor graph: ' || array_to_string(v_bad, '; ');
  END IF;
END
$rds_activation_30$;
